    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Staff")
            questions.pharmacistCandidates.match(filter)?.let { h -> return store.pharmacistCandidates().map { it.toRow() } }
        if (shape == "Staff")
            questions.technicianCandidates.match(filter)?.let { h -> return store.technicianCandidates().map { it.toRow() } }
