            questions.filledPrescriptionCandidates.match(filter)?.let { h -> return store.filledPrescriptionCandidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.voidedCandidates.match(filter)?.let { h -> return store.voidedCandidates().map { it.toRow() } }
        if (shape == "Fill")
            questions.consumingFillCandidates.match(filter)?.let { h -> return store.consumingFillCandidates().map { it.toRow() } }
        if (shape == "Fill")
            questions.counsellingDueCandidates.match(filter)?.let { h -> return store.counsellingDueCandidates().map { it.toRow() } }
        if (shape == "Fill")
            questions.readyForPickupCandidates.match(filter)?.let { h -> return store.readyForPickupCandidates().map { it.toRow() } }
        if (shape == "RefillTask")
            questions.overdueRefillTaskCandidates.match(filter)?.let { h -> return store.overdueRefillTaskCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Prescription")
            questions.autoRefillCandidates.match(filter)?.let { h -> return store.autoRefillCandidates().map { it.toRow() } }
        if (shape == "Claim")
            questions.pendingClaimCandidates.match(filter)?.let { h -> return store.pendingClaimCandidates().map { it.toRow() } }
        if (shape == "Claim")
            questions.staleClaimCandidates.match(filter)?.let { h -> return store.staleClaimCandidates(h.instant(0)).map { it.toRow() } }
        if (shape == "Staff")
            questions.remindLicenceCandidates.match(filter)?.let { h -> return store.remindLicenceCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "StockLot")
            questions.quarantineExpiredCandidates.match(filter)?.let { h -> return store.quarantineExpiredCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "StockLot")
            questions.quarantineRecalledCandidates.match(filter)?.let { h -> return store.quarantineRecalledCandidates().map { it.toRow() } }
        if (shape == "Fill")
            questions.noticeRecallCandidates.match(filter)?.let { h -> return store.noticeRecallCandidates().map { it.toRow() } }
        if (shape == "Drug")
            questions.reorderCandidates.match(filter)?.let { h -> return store.reorderCandidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.alertAllergyCandidates.match(filter)?.let { h -> return store.alertAllergyCandidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.alertInteractionCandidates.match(filter)?.let { h -> return store.alertInteractionCandidates().map { it.toRow() } }
        if (shape == "Fill")
            questions.logControlledCandidates.match(filter)?.let { h -> return store.logControlledCandidates().map { it.toRow() } }
        if (shape == "Fill")
            questions.alertCounterCandidates.match(filter)?.let { h -> return store.alertCounterCandidates().map { it.toRow() } }
        if (shape == "RefillRefusal")
            questions.askPrescriberCandidates.match(filter)?.let { h -> return store.askPrescriberCandidates().map { it.toRow() } }
        if (shape == "RefillTask")
            questions.nagRefillTaskCandidates.match(filter)?.let { h -> return store.nagRefillTaskCandidates(h.date(0), h.date(1)).map { it.toRow() } }
        if (shape == "Fill")
            questions.submitClaimCandidates.match(filter)?.let { h -> return store.submitClaimCandidates().map { it.toRow() } }
        if (shape == "Claim")
            questions.followUpClaimCandidates.match(filter)?.let { h -> return store.followUpClaimCandidates(h.instant(0), h.instant(1)).map { it.toRow() } }
        if (shape == "LicenceRenewal")
            questions.never1Candidates.match(filter)?.let { h -> return store.never1Candidates().map { it.toRow() } }
        if (shape == "Drug")
            questions.never2Candidates.match(filter)?.let { h -> return store.never2Candidates().map { it.toRow() } }
        if (shape == "PriceChange")
            questions.never4Candidates.match(filter)?.let { h -> return store.never4Candidates().map { it.toRow() } }
        if (shape == "StockLot")
            questions.never7Candidates.match(filter)?.let { h -> return store.never7Candidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.never10Candidates.match(filter)?.let { h -> return store.never10Candidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.never11Candidates.match(filter)?.let { h -> return store.never11Candidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.never12Candidates.match(filter)?.let { h -> return store.never12Candidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.never13Candidates.match(filter)?.let { h -> return store.never13Candidates().map { it.toRow() } }
        if (shape == "Prescription")
            questions.never14Candidates.match(filter)?.let { h -> return store.never14Candidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        "ReadyForPickup" -> store.readyForPickupCapture(instance)?.toValues()
        else -> null
    }
}

private fun List<QConst>.date(i: Int): LocalDate = (this[i] as QConst.QDate).v
private fun List<QConst>.instant(i: Int): Instant = (this[i] as QConst.QDateTime).v

