    prescription = fields["prescription"] as Ref.Persisted,
)

fun AutoRefillCancellationRow.toRow(): Row = Row("AutoRefillCancellation", key, buildMap {
    put("prescription", prescription)
})

fun Row.toClaimRow(): ClaimRow = ClaimRow(
    key = key,
    fill = fields["fill"] as Ref.Persisted,
    plan = fields["plan"] as Ref.Persisted,
    amount = fields["amount"] as BigDecimal,
    claimKey = fields["claimKey"] as String,
    submittedAt = fields["submittedAt"] as Instant,
)

fun ClaimRow.toRow(): Row = Row("Claim", key, buildMap {
    put("fill", fill)
    put("plan", plan)
    put("amount", amount)
    put("claimKey", claimKey)
    put("submittedAt", submittedAt)
})

fun Row.toClaimResponseRow(): ClaimResponseRow = ClaimResponseRow(
    key = key,
    claim = fields["claim"] as Ref.Persisted,
    outcome = ClaimOutcome.of(fields["outcome"] as String),
    paidAmount = fields["paidAmount"] as BigDecimal,
    patientPays = fields["patientPays"] as BigDecimal,
    respondedAt = fields["respondedAt"] as Instant,
)

fun ClaimResponseRow.toRow(): Row = Row("ClaimResponse", key, buildMap {
    put("claim", claim)
    put("outcome", outcome.word)
    put("paidAmount", paidAmount)
    put("patientPays", patientPays)
    put("respondedAt", respondedAt)
})

fun Row.toClaimFollowUpRow(): ClaimFollowUpRow = ClaimFollowUpRow(
    key = key,
    claim = fields["claim"] as Ref.Persisted,
    followedUpAt = fields["followedUpAt"] as Instant,
)

fun ClaimFollowUpRow.toRow(): Row = Row("ClaimFollowUp", key, buildMap {
    put("claim", claim)
    put("followedUpAt", followedUpAt)
})

fun Row.toControlledInventorySnapshotRow(): ControlledInventorySnapshotRow = ControlledInventorySnapshotRow(
    key = key,
    drug = fields["drug"] as Ref.Persisted,
    onHand = (fields["onHand"] as Number).toInt(),
    takenOn = fields["takenOn"] as LocalDate,
)

fun ControlledInventorySnapshotRow.toRow(): Row = Row("ControlledInventorySnapshot", key, buildMap {
    put("drug", drug)
    put("onHand", onHand)
    put("takenOn", takenOn)
})

fun Map<String, Any?>.toReadyForPickupCapture(): ReadyForPickupCapture = ReadyForPickupCapture(
    readyOn = this["readyOn"] as LocalDate,
)

fun ReadyForPickupCapture.toValues(): Map<String, Any?> = buildMap {
    put("readyOn", readyOn)
}
